fn frame(t: i32) {
    let w: i32 = host::display::width();
    let count: i32 = host::display::state_get(0) + 1;
    host::display::state_set(0, count);
    host::display::clear(0x101010);
    host::display::draw_string(8, 10, "COUNT", 0x808080, 2);
    host::display::draw_number(84, 10, count, 0x00ff00, 2);
    let mut bw: i32 = count * 2;
    if bw > w { bw = w; }
    host::display::fill_rect(0, 60, bw, 24, 0x00ff00);
    host::display::present();
}
